var registerUser = async (payload) => {
  const { name, password, phoneNumber } = payload;
  const email = payload.email.trim().toLowerCase();
  const isUserExists = await prisma.user.findUnique({
    where: { email }
  });
  if (isUserExists) {
    throw new Error("User with this email already exists");
  }
  const saltRounds = Number(config_default.bcrypt_salt_rounds) || 10;
  const hashedPassword = await bcrypt.hash(password, saltRounds);
  const otpValue = crypto.randomInt(1e5, 1e6).toString();
  const expirationSeconds = 60 * 5;
  const otpkey = `Donor-Register-otp:${email}`;
  await redisClient.set(otpkey, otpValue, {
    EX: expirationSeconds
  });
  const donorregisterkey = `Donor-Register-data:${email}`;
  const redisUserDataPaylod = {
    name,
    email,
    password: hashedPassword,
    phoneNumber
  };
  await redisClient.set(donorregisterkey, JSON.stringify(redisUserDataPaylod), {
    EX: expirationSeconds
  });
  const tempatePath = path3.join(
    process.cwd(),
    "src/app/templates/registration-user-otp.ejs"
  );
  const templateData = {
    name,
    email,
    otp: otpValue,
    expirationMinutes: expirationSeconds / 60
  };
  const html = await ejs.renderFile(tempatePath, templateData);
  await transporter.sendMail({
    from: config_default.smtp_sender,
    to: email,
    subject: "Email Verification",
    html
  });
  return {
    message: "Verification OTP sent to your email successfully"
  };
};
var verifyDonorEmail = async (payload) => {
  const otp = payload.otp;
  const email = payload.email.trim().toLowerCase();
  const isUserExist = await prisma.user.findUnique({
    where: { email }
  });
  if (isUserExist?.status === UserStatus.BLOCKED) {
    throw new Error("User is Blocked");
  }
  if (isUserExist?.isVerified) {
    throw new Error("Email Already Verified");
  }
  const otpKey = `Donor-Register-otp:${email}`;
  const redisOtp = await redisClient.get(otpKey);
  if (!redisOtp) {
    throw new Error("Invalid or Expired OTP");
  }
  if (String(redisOtp).trim() !== String(otp).trim()) {
    throw new Error("OTP Does Not Match");
  }
  await redisClient.del(otpKey);
  const donorregisterkey = `Donor-Register-data:${email}`;
  const redisDonorData = await redisClient.get(donorregisterkey);
  if (!redisDonorData) {
    throw new Error("Donor Data Does Not Exist or Expired");
  }
  const DonorPayload = JSON.parse(redisDonorData);
  const [createdUser, donor] = await prisma.$transaction(async (tx) => {
    const user = await tx.user.create({
      data: {
        name: DonorPayload.name,
        email: DonorPayload.email,
        password: DonorPayload.password,
        phoneNumber: DonorPayload.phoneNumber || "",
        role: Role.DONOR,
        isVerified: true
      },
      omit: { password: true }
    });
    const createdDonor = await tx.donor.create({
      data: {
        userId: user.id,
        name: DonorPayload.name,
        email: DonorPayload.email,
        phoneNumber: DonorPayload.phoneNumber || ""
      }
    });
    return [user, createdDonor];
  });
  await redisClient.del(donorregisterkey);
  const templatePath = path3.join(
    process.cwd(),
    "src/app/templates/Donor-welcome-email.ejs"
  );
  const templateData = {
    name: createdUser.name
  };
  try {
    const html = await ejs.renderFile(templatePath, templateData);
    await transporter.sendMail({
      from: config_default.smtp_sender,
      to: email,
      subject: "Welcome To DurjogSheba System",
      html
    });
  } catch (err) {
    console.error("Welcome email send failed:", err);
  }
  const jwtPayload = {
    userId: createdUser.id,
    name: createdUser.name,
    email: createdUser.email,
    role: createdUser.role
  };
  const accessToken = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_access_secret,
    config_default.jwt_access_expires_in
  );
  const refreshToken3 = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_refresh_secret,
    config_default.jwt_refresh_expires_in
  );
  return {
    user: createdUser,
    donor,
    accessToken,
    refreshToken: refreshToken3
  };
};
var loginUser = async (payload) => {
  const { password } = payload;
  const email = payload.email.trim().toLowerCase();
  const user = await prisma.user.findUnique({
    where: { email }
  });
  if (user?.status === UserStatus.BLOCKED) {
    throw new Error("User is Blocked");
  }
  if (!user) {
    throw new Error("User not found");
  }
  const isPasswordMatched = await bcrypt.compare(password, user.password);
  if (!isPasswordMatched) {
    throw new Error("Invalid credentials");
  }
  const jwtPayload = {
    userId: user.id,
    name: user.name,
    email: user.email,
    role: user.role
  };
  const accessToken = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_access_secret,
    config_default.jwt_access_expires_in
  );
  const refreshToken3 = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_refresh_secret,
    config_default.jwt_refresh_expires_in
  );
  return {
    accessToken,
    refreshToken: refreshToken3
  };
};
