var refreshToken = async (token) => {
  const verifiedRefreshToken = jwtUtils.verifyToken(
    token,
    config_default.jwt_refresh_secret
  );
  if (!verifiedRefreshToken.success || !verifiedRefreshToken.data) {
    throw new Error(
      config_default.node_env === "development" ? verifiedRefreshToken.error : "Invalid refresh token"
    );
  }
  const data = verifiedRefreshToken.data;
  const user = await prisma.user.findUnique({
    where: { id: data.userId }
  });
  if (!user) {
    throw new Error("User is inactive or not found");
  }
  const jwtPayload = {
    userId: user.id,
    name: user.name,
    email: user.email,
    role: user.role
  };
  const accessToken = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_access_secret,
    config_default.jwt_access_expires_in
  );
  const newRefreshToken = jwtUtils.createToken(
    jwtPayload,
    config_default.jwt_refresh_secret,
    config_default.jwt_refresh_expires_in
  );
  return {
    accessToken,
    refreshToken: newRefreshToken
  };
};
var ForgetPasswrod = async (payload) => {
  const email = payload.email.trim().toLowerCase();
  const isUserExist = await prisma.user.findUnique({
    where: { email }
  });
  if (!isUserExist) {
    throw new Error("User not found");
  }
  const otp = crypto.randomInt(1e5, 1e6).toString();
  const expirationSeconds = 60 * 5;
  const key = `forget-password-otp:${isUserExist.email.trim().toLowerCase()}`;
  await redisClient.set(key, otp, {
    EX: expirationSeconds
  });
  const tempatePath = path3.join(
    process.cwd(),
    "src/app/templates/forgot-password.ejs"
  );
  const templateData = {
    name: isUserExist.name,
    otp,
    expirationMinutes: expirationSeconds / 60
  };
  const html = await ejs.renderFile(tempatePath, templateData);
  await transporter.sendMail({
    from: config_default.smtp_sender,
    to: isUserExist.email,
    subject: "Forget Password",
    html
  });
  return {
    message: "OTP sent to your email successfully"
  };
};
var ResetPasswrod = async (payload) => {
  const { email, otp, newPassword } = payload;
  const normalizedEmail = email.trim().toLowerCase();
  const isUserExist = await prisma.user.findUnique({
    where: { email: normalizedEmail }
  });
  if (!isUserExist) {
    throw new Error("User not found");
  }
  const key = `forget-password-otp:${isUserExist.email}`;
  const redisOtp = await redisClient.get(key);
  if (!redisOtp) {
    throw new Error("Invalid OTP");
  }
  if (redisOtp !== otp) {
    throw new Error("OTP Does Not Match");
  }
  const hashedNewPassword = await bcrypt.hash(
    newPassword,
    Number(config_default.bcrypt_salt_rounds)
  );
  await prisma.user.update({
    where: {
      email: isUserExist.email
    },
    data: {
      password: hashedNewPassword
    }
  });
  await redisClient.del([key]);
  const expirationSeconds = 60 * 5;
  const tempatePath = path3.join(
    process.cwd(),
    "src/app/templates/reset-password-success.ejs"
  );
  const templateData = {
    name: isUserExist.name,
    otp,
    expirationMinutes: expirationSeconds / 60
  };
  const html = await ejs.renderFile(tempatePath, templateData);
  await transporter.sendMail({
    from: config_default.smtp_sender,
    to: isUserExist.email,
    subject: "Reset Password",
    html
  });
};
