// src/app/module/user/user.service.ts
var uploadProfileImage = async (buffer, userId) => {
  const currentUser = await prisma.user.findUnique({
    where: {
      id: userId
    },
    select: {
      imagePublicId: true,
      imageUrl: true
    }
  });
  if (!currentUser) {
    throw new Error("User not found");
  }
  const cloudinaryResult = await new Promise(
    (resolve, reject) => {
      cloudinary.uploader.upload_stream(
        {
          resource_type: "auto",
          folder: "durjog-sheba/profiles"
        },
        (error, result) => {
          if (error) {
            return reject(error);
          }
          if (!result) {
            return reject(new Error("No result returned from Cloudinary"));
          }
          resolve(result);
        }
      ).end(buffer);
    }
  );
  const updatedUser = await prisma.user.update({
    where: {
      id: userId
    },
    data: {
      imageUrl: cloudinaryResult.secure_url,
      imagePublicId: cloudinaryResult.public_id
    },
    omit: {
      password: true
    }
  });
  if (currentUser.imagePublicId) {
    try {
      await cloudinary.uploader.destroy(currentUser.imagePublicId);
    } catch (err) {
      console.error("Failed to delete old image from Cloudinary:", err);
    }
  }
  return updatedUser;
};
var UserServices = {
  uploadProfileImage
};

// src/app/module/user/user.controller.ts
var uploadProfileImage2 = async (req, res) => {
  try {
    if (!req.file || !req.file.buffer) {
      return res.status(400).json({
        success: false,
        message: "No image file provided"
      });
    }
    const userId = req.user?.userId;
    if (!userId) {
      return res.status(401).json({
        success: false,
        message: "Unauthorized access"
      });
    }
    const result = await UserServices.uploadProfileImage(
      req.file.buffer,
      userId
    );
    res.status(200).json({
      success: true,
      statusCode: 200,
      message: "Profile image uploaded successfully",
      data: result
    });
  } catch (error) {
    res.status(400).json({
      success: false,
      message: error.message || "Failed to upload profile image"
    });
  }
};
var UserController = {
  uploadProfileImage: uploadProfileImage2
};

