// src/app/lib/bkash.ts
var getBkashIdToken = async () => {
  try {
    const IdTokenKey = "bkash:idToken";
    const RefreshTokenKey = "bkash:refreshToken";
    const cachedIdToken = await redisClient.get(IdTokenKey);
    const cachedIdTokenTTL = await redisClient.ttl(IdTokenKey);
    const cachedRefreshToken = await redisClient.get(RefreshTokenKey);
    const cachedRefreshTokenTTL = await redisClient.ttl(RefreshTokenKey);
    if (cachedIdToken && cachedIdTokenTTL > 600) {
      return cachedIdToken;
    }
    if ((cachedIdTokenTTL <= 600 || !cachedIdToken) && cachedRefreshToken && cachedRefreshTokenTTL > 600) {
      try {
        const refreshTokenResponse = await fetch(`${config_default.bkash_base_url}/tokenized/checkout/token/refresh`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
            username: config_default.bkash_username,
            password: config_default.bkash_password
          },
          body: JSON.stringify({
            app_key: config_default.bkash_app_key,
            app_secret: config_default.bkash_app_secret,
            refresh_token: cachedRefreshToken
          })
        });
        if (refreshTokenResponse.ok) {
          const bkashRefreshTokenResult = await refreshTokenResponse.json();
          if (bkashRefreshTokenResult && bkashRefreshTokenResult.id_token) {
            const refreshedIdToken = bkashRefreshTokenResult.id_token;
            await redisClient.set(IdTokenKey, refreshedIdToken, {
              expiration: {
                type: "EX",
                value: 60 * 60
              }
            });
            if (bkashRefreshTokenResult.refresh_token) {
              await redisClient.set(RefreshTokenKey, bkashRefreshTokenResult.refresh_token, {
                expiration: {
                  type: "EX",
                  value: 60 * 60 * 24 * 28
                }
              });
            }
            return refreshedIdToken;
          }
        }
      } catch (refreshError) {
        console.error("bKash token refresh failed, falling back to grant token:", refreshError);
      }
    }
    const response = await fetch(`${config_default.bkash_base_url}/tokenized/checkout/token/grant`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        username: config_default.bkash_username,
        password: config_default.bkash_password
      },
      body: JSON.stringify({
        app_key: config_default.bkash_app_key,
        app_secret: config_default.bkash_app_secret
      })
    });
    if (!response.ok) {
      throw new Error("Bkash Access Token Grant Failed");
    }
    const result = await response.json();
    if (!result || !result.id_token) {
      throw new Error("Invalid response from bKash grant token API");
    }
    const newIdToken = result.id_token;
    await redisClient.set(IdTokenKey, newIdToken, {
      expiration: {
        type: "EX",
        value: 60 * 60
      }
    });
    if (result.refresh_token) {
      await redisClient.set(RefreshTokenKey, result.refresh_token, {
        expiration: {
          type: "EX",
          value: 60 * 60 * 24 * 28
        }
      });
    }
    return newIdToken;
  } catch (error) {
    throw new Error(error.message || "Failed to get bKash ID Token");
  }
};

// src/app/module/donation/donation.service.ts
import crypto2 from "crypto";
var createBkashPayment = async (userId, amount) => {
  const idToken = await getBkashIdToken();
  const transactionId = `TRX-${crypto2.randomBytes(4).toString("hex").toUpperCase()}`;
  const donation = await prisma.donation.create({
    data: {
      donorId: userId,
      amount,
      currency: "BDT",
      transactionId,
      paymentGateway: "bKash",
      status: PaymentStatus.PENDING
    }
  });
  const response = await fetch(`${config_default.bkash_base_url}/tokenized/checkout/create`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
      authorization: idToken,
      "x-app-key": config_default.bkash_app_key
    },
    body: JSON.stringify({
      mode: "0011",
      payerReference: "1",
      callbackURL: `${config_default.bak_url}/api/v1/donations/bkash/callback/${donation.id}`,
      amount: amount.toString(),
      currency: "BDT",
      intent: "sale",
      merchantInvoiceNumber: transactionId
    })
  });
  const result = await response.json();
  if (!response.ok || result.statusCode !== "0000") {
    await prisma.donation.update({
      where: { id: donation.id },
      data: { status: PaymentStatus.FAILED }
    });
    throw new Error(result.statusMessage || "Failed to create bKash payment");
  }
  return {
    bkashURL: result.bkashURL,
    paymentID: result.paymentID,
    donationId: donation.id
  };
};
var executeBkashPayment = async (paymentID, donationId) => {
  const existingDonation = await prisma.donation.findUnique({
    where: { id: donationId }
  });
  if (!existingDonation) {
    throw new Error("Donation record not found");
  }
  if (existingDonation.status === PaymentStatus.COMPLETED) {
    return existingDonation;
  }
  const idToken = await getBkashIdToken();
  const response = await fetch(`${config_default.bkash_base_url}/tokenized/checkout/execute`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
      authorization: idToken,
      "x-app-key": config_default.bkash_app_key
    },
    body: JSON.stringify({
      paymentID
    })
  });
  const result = await response.json();
  if (!response.ok || result.statusCode !== "0000") {
    await prisma.donation.update({
      where: { id: donationId },
      data: { status: PaymentStatus.FAILED }
    });
    throw new Error(result.statusMessage || "bKash payment execution failed");
  }
  const updatedDonation = await prisma.donation.update({
    where: { id: donationId },
    data: { status: PaymentStatus.COMPLETED }
  });
  return updatedDonation;
};
var DonationService = {
  createBkashPayment,
  executeBkashPayment
};

// src/app/module/donation/donation.controller.ts
var initiateDonation = async (req, res) => {
  try {
    const userId = req.user.userId;
    const { amount } = req.body;
    const result = await DonationService.createBkashPayment(userId, amount);
    res.status(201).json({
      success: true,
      statusCode: 201,
      message: "bKash payment initiated successfully",
      data: result
    });
  } catch (error) {
    res.status(400).json({ success: false, message: error.message || "Failed to initiate payment" });
  }
};
var bkashCallback = async (req, res) => {
  try {
    let donationId = req.params.donationId || req.query.donationId;
    let paymentID = req.query.paymentID;
    let status = req.query.status;
    if (donationId && donationId.includes("?")) {
      const parts = donationId.split("?");
      donationId = parts[0];
      const extraQuery = parts.slice(1).join("&");
      const searchParams = new URLSearchParams(extraQuery);
      if (!paymentID && searchParams.has("paymentID")) {
        paymentID = searchParams.get("paymentID");
      }
      if (!status && searchParams.has("status")) {
        status = searchParams.get("status");
      }
    }
    if (!donationId) {
      if (config_default.frontend_url) {
        return res.redirect(`${config_default.frontend_url}/payment/failed?message=Donation ID is missing`);
      }
      return res.status(400).json({ success: false, message: "Donation ID is missing in callback" });
    }
    if (status === "success" || status === "completed") {
      if (!paymentID) {
        if (config_default.frontend_url) {
          return res.redirect(`${config_default.frontend_url}/payment/failed?message=Payment ID is missing`);
        }
        return res.status(400).json({ success: false, message: "Payment ID is missing" });
      }
      const updatedDonation = await DonationService.executeBkashPayment(paymentID, donationId);
      if (config_default.frontend_url) {
        return res.redirect(
          `${config_default.frontend_url}/payment/success?donationId=${updatedDonation.id}&trxID=${updatedDonation.transactionId}&amount=${updatedDonation.amount}`
        );
      }
      return res.status(200).json({
        success: true,
        statusCode: 200,
        message: "bKash payment executed and completed successfully",
        data: updatedDonation
      });
    } else {
      await prisma.donation.update({
        where: { id: donationId },
        data: { status: PaymentStatus.FAILED }
      });
      if (config_default.frontend_url) {
        return res.redirect(`${config_default.frontend_url}/payment/failed?donationId=${donationId}&status=${status || "failed"}`);
      }
      return res.status(400).json({
        success: false,
        statusCode: 400,
        message: `bKash payment ${status || "failed"}`
      });
    }
  } catch (error) {
    if (config_default.frontend_url) {
      return res.redirect(`${config_default.frontend_url}/payment/failed?message=${encodeURIComponent(error.message || "Payment execution failed")}`);
    }
    return res.status(500).json({
      success: false,
      statusCode: 500,
      message: error.message || "Internal server error during payment execution"
    });
  }
};
var DonationController = {
  initiateDonation,
  bkashCallback
};

